import React, { useEffect, useState } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import {
  getCookieConsentState,
  setCookieConsentState,
  hasAnalyticsConsent,
} from "../utils/cookieConsent";
import { grantAnalyticsConsent, revokeAnalyticsConsent } from "../utils/analytics";

type Panel = "banner" | "manager" | "hidden";

const CookieBanner: React.FC = () => {
  const { t } = useTranslation("common");
  const [panel, setPanel] = useState<Panel>("hidden");
  const [analyticsChecked, setAnalyticsChecked] = useState(true);

  useEffect(() => {
    const state = getCookieConsentState();
    if (state === "unset") {
      setPanel("banner");
    }
    setAnalyticsChecked(state !== "rejected");
  }, []);

  const applyConsent = (accepted: boolean) => {
    setCookieConsentState(accepted ? "accepted" : "rejected");
    if (accepted) {
      grantAnalyticsConsent();
    } else {
      revokeAnalyticsConsent();
    }
    setPanel("hidden");
  };

  const handleAccept = () => applyConsent(true);
  const handleDecline = () => applyConsent(false);

  const handleSavePreferences = () => {
    applyConsent(analyticsChecked);
  };

  // Expose openManager globally so the footer link can trigger it
  useEffect(() => {
    (window as any).__ccsOpenCookieManager = () => {
      setAnalyticsChecked(hasAnalyticsConsent());
      setPanel("manager");
    };
    return () => {
      delete (window as any).__ccsOpenCookieManager;
    };
  }, []);

  if (panel === "hidden") return null;

  return (
    <>
      {/* Backdrop for manager */}
      {panel === "manager" && (
        <div
          className="fixed inset-0 z-[998] bg-black/60 backdrop-blur-sm"
          onClick={() => setPanel("hidden")}
        />
      )}

      {/* Banner */}
      {panel === "banner" && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="cookie-banner-title"
          className="fixed bottom-0 left-0 right-0 z-[999]"
          style={{
            background: "rgba(10, 13, 20, 0.97)",
            borderTop: "1px solid var(--border-2)",
            backdropFilter: "blur(20px)",
            WebkitBackdropFilter: "blur(20px)",
          }}
        >
          <div
            className="cc-container flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"
            style={{ padding: "var(--space-4) 0" }}
          >
            <div className="flex-1 min-w-0">
              <p
                id="cookie-banner-title"
                className="font-mono text-[11px] tracking-[0.1em] uppercase"
                style={{ color: "var(--blue)", marginBottom: 4 }}
              >
                {t("cookies.bannerTitle")}
              </p>
              <p className="font-body text-[13px] text-[var(--text-2)] leading-relaxed max-w-xl">
                {t("cookies.bannerText")}
              </p>
            </div>

            <div className="flex flex-wrap items-center gap-2 shrink-0">
              <button
                onClick={() => {
                  setAnalyticsChecked(true);
                  setPanel("manager");
                }}
                className="font-mono text-[11px] tracking-[0.08em] text-[var(--text-3)] hover:text-[var(--text-1)] transition-colors px-3 py-2 underline underline-offset-2"
              >
                {t("footer.manageCookies")}
              </button>
              <button
                onClick={handleDecline}
                className="btn-secondary"
                style={{ padding: "9px 18px", fontSize: 13 }}
              >
                {t("cookies.decline")}
              </button>
              <button
                onClick={handleAccept}
                className="btn-primary"
                style={{ padding: "9px 18px", fontSize: 13 }}
              >
                {t("cookies.accept")}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Manager modal */}
      {panel === "manager" && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="cookie-manager-title"
          className="fixed inset-0 z-[999] flex items-end sm:items-center justify-center p-4"
          style={{ pointerEvents: "none" }}
        >
          <div
            className="w-full max-w-md rounded-[var(--radius-lg)] overflow-hidden"
            style={{
              background: "var(--bg-card)",
              border: "1px solid var(--border-2)",
              boxShadow: "0 24px 80px rgba(0,0,0,0.6)",
              pointerEvents: "all",
            }}
          >
            {/* Header */}
            <div
              className="flex items-center justify-between"
              style={{
                padding: "var(--space-5) var(--space-5) var(--space-4)",
                borderBottom: "1px solid var(--border-1)",
              }}
            >
              <h2
                id="cookie-manager-title"
                className="font-mono text-[13px] tracking-[0.08em] font-medium text-[var(--text-1)]"
              >
                {t("cookies.managerTitle")}
              </h2>
              <button
                onClick={() => setPanel("hidden")}
                aria-label={t("cookies.close")}
                className="text-[var(--text-3)] hover:text-[var(--text-1)] transition-colors"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <path d="M18 6L6 18M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Cookie rows */}
            <div
              className="flex flex-col gap-0"
              style={{ padding: "var(--space-4) var(--space-5)" }}
            >
              {/* Necessary — always on */}
              <CookieRow
                label={t("cookies.necessaryLabel")}
                desc={t("cookies.necessaryDesc")}
                checked={true}
                disabled={true}
                onChange={() => {}}
              />

              {/* Analytics */}
              <CookieRow
                label={t("cookies.analyticsLabel")}
                desc={t("cookies.analyticsDesc")}
                checked={analyticsChecked}
                disabled={false}
                onChange={setAnalyticsChecked}
              />
            </div>

            {/* Footer */}
            <div
              className="flex justify-end gap-3"
              style={{
                padding: "var(--space-4) var(--space-5)",
                borderTop: "1px solid var(--border-1)",
              }}
            >
              <button
                onClick={handleSavePreferences}
                className="btn-primary"
                style={{ padding: "9px 20px", fontSize: 13 }}
              >
                {t("cookies.savePreferences")}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

interface CookieRowProps {
  label: string;
  desc: string;
  checked: boolean;
  disabled: boolean;
  onChange: (val: boolean) => void;
}

const CookieRow: React.FC<CookieRowProps> = ({ label, desc, checked, disabled, onChange }) => (
  <div
    className="flex items-start justify-between gap-4"
    style={{ padding: "var(--space-3) 0", borderBottom: "1px solid var(--border-1)" }}
  >
    <div className="flex-1 min-w-0">
      <p className="font-mono text-[11px] tracking-[0.08em] font-medium text-[var(--text-1)] uppercase">
        {label}
      </p>
      <p className="font-body text-[12px] text-[var(--text-3)] mt-1 leading-relaxed">
        {desc}
      </p>
    </div>
    <button
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      onClick={() => !disabled && onChange(!checked)}
      style={{
        width: 40,
        height: 22,
        borderRadius: 11,
        border: "none",
        cursor: disabled ? "not-allowed" : "pointer",
        background: checked ? "var(--blue)" : "var(--border-2)",
        position: "relative",
        flexShrink: 0,
        transition: "background 0.2s ease",
        opacity: disabled ? 0.5 : 1,
        marginTop: 2,
      }}
    >
      <span
        style={{
          position: "absolute",
          top: 3,
          left: checked ? 21 : 3,
          width: 16,
          height: 16,
          borderRadius: "50%",
          background: "#fff",
          transition: "left 0.2s ease",
        }}
      />
    </button>
  </div>
);

export default CookieBanner;
