import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { useTranslation, useI18next } from "gatsby-plugin-react-i18next";
import images from "../images";
import CookieBanner from "./CookieBanner";

interface LayoutProps {
  children: React.ReactNode;
  activeNav?: "services" | "industries" | "process" | "case-studies" | "about";
}

const Layout: React.FC<LayoutProps> = ({ children, activeNav }) => {
  const { t } = useTranslation("common");
  const { language, languages, changeLanguage } = useI18next();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [currentYear, setYear] = React.useState<number | null>(null);

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const navLinks = [
    { key: "services",      label: t("nav.services"),    to: "/services/" },
    { key: "industries",    label: t("nav.industries"),  to: "/industries/" },
    { key: "process",       label: t("nav.process"),     to: "/process/" },
    { key: "case-studies",  label: t("nav.caseStudies"), to: "/case-studies/" },
    { key: "about",         label: t("nav.about"),       to: "/about/" },
  ];

  const langLabels: Record<string, string> = { en: "EN", fr: "FR", es: "ES" };

  return (
    <>
      {/* ===== NAV ===== */}
      <nav
        className="fixed top-0 left-0 right-0 z-50 h-16 transition-all duration-300"
        style={scrolled ? {
          background: "rgba(7, 9, 13, 0.92)",
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          borderBottom: "1px solid rgba(45, 110, 246, 0.10)",
        } : {
          background: "transparent",
          borderBottom: "1px solid transparent",
        }}
      >
        <div className="cc-container h-full flex items-center justify-between gap-4">
          {/* Logo */}
          <Link to="/" className="flex flex-col gap-px shrink-0">
            <img src={images.logo.src} alt={images.logo.alt} className="h-12 w-auto" />
          </Link>

          {/* Desktop nav links */}
          <div className="hidden md:flex items-center gap-2">
            {navLinks.map((l) => (
              <Link
                key={l.key}
                to={l.to}
                className={[
                  "font-body text-sm px-3 py-1.5 rounded-[var(--radius-sm)] transition-colors duration-150 whitespace-nowrap",
                  activeNav === l.key
                    ? "text-[var(--text-1)] bg-[var(--blue-dim)]"
                    : "text-[var(--text-2)] hover:text-[var(--text-1)] hover:bg-[var(--blue-dim)]",
                ].join(" ")}
              >
                {l.label}
              </Link>
            ))}
          </div>

          {/* Right side */}
          <div className="flex items-center gap-4 shrink-0">
            {/* Language switcher */}
            <div className="hidden sm:flex items-center gap-1.5 font-mono text-[11px] tracking-[0.08em] text-[var(--text-3)]">
              {languages.map((lng, i) => (
                <React.Fragment key={lng}>
                  {i > 0 && <span className="opacity-40">·</span>}
                  <button
                    onClick={() => void changeLanguage(lng)}
                    className={[
                      "hover:text-[var(--text-1)] transition-colors duration-150",
                      language === lng ? "text-[var(--text-1)]" : "",
                    ].join(" ")}
                  >
                    {langLabels[lng] ?? lng.toUpperCase()}
                  </button>
                </React.Fragment>
              ))}
            </div>
            <div className="hidden sm:block w-px h-5 bg-[var(--border-1)]" />
            <Link
              to="/contact/"
              className="btn-primary"
              style={{ padding: "9px 20px", fontSize: "14px" }}
            >
              {t("nav.cta")}
            </Link>
            {/* Mobile menu toggle */}
            <button
              className="md:hidden text-[var(--text-2)] hover:text-[var(--text-1)] transition-colors"
              onClick={() => setMenuOpen(!menuOpen)}
              aria-label="Toggle menu"
            >
              <svg width="22" height="22" viewBox="0 0 22 22" fill="none">
                {menuOpen ? (
                  <path d="M4 4l14 14M18 4L4 18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                ) : (
                  <>
                    <path d="M3 6h16M3 11h16M3 16h16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                  </>
                )}
              </svg>
            </button>
          </div>
        </div>

        {/* Mobile dropdown */}
        {menuOpen && (
          <div
            className="md:hidden absolute top-16 left-0 right-0 border-t border-[var(--border-1)] py-4"
            style={{ background: "rgba(7, 9, 13, 0.96)", backdropFilter: "blur(20px)" }}
          >
            <div className="cc-container flex flex-col gap-1">
              {navLinks.map((l) => (
                <Link
                  key={l.key}
                  to={l.to}
                  className="font-body text-sm px-3 py-2 rounded-[var(--radius-sm)] text-[var(--text-2)] hover:text-[var(--text-1)] hover:bg-[var(--blue-dim)] transition-colors"
                  onClick={() => setMenuOpen(false)}
                >
                  {l.label}
                </Link>
              ))}
              <div className="flex items-center gap-3 px-3 pt-3 mt-2 border-t border-[var(--border-1)]">
                {languages.map((lng) => (
                  <button
                    key={lng}
                    onClick={() => { void changeLanguage(lng); setMenuOpen(false); }}
                    className={[
                      "font-mono text-[11px] tracking-[0.08em] transition-colors",
                      language === lng ? "text-[var(--text-1)]" : "text-[var(--text-3)] hover:text-[var(--text-1)]",
                    ].join(" ")}
                  >
                    {langLabels[lng] ?? lng.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </nav>

      {/* ===== PAGE CONTENT ===== */}
      <main>{children}</main>

      {/* ===== FOOTER ===== */}
      <footer className="border-t border-[var(--border-1)] bg-[var(--bg-surface)]" style={{ padding: "var(--space-8) 0 var(--space-6)" }}>
        <div className="cc-container">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
            {/* Brand */}
            <div className="lg:col-span-1">
              <Link to="/" className="">
                <img src={images.logo.src} alt={images.logo.alt} className="h-12 w-auto" />
              </Link>
              <p className="font-body text-[13px] text-[var(--text-3)] mt-4 max-w-[320px]">
                {t("footer.tagline")}
              </p>
              <p className="font-body text-[13px] text-[var(--text-3)] mt-2">{t("footer.location")}</p>
              <div className="flex gap-3 mt-5">
                {[
                  { href: "https://linkedin.com", label: "LinkedIn", icon: "M19 3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14m-.5 15.5v-5.3a3.26 3.26 0 0 0-3.26-3.26c-.85 0-1.84.52-2.32 1.3v-1.11h-2.79v8.37h2.79v-4.93c0-.77.62-1.4 1.39-1.4a1.4 1.4 0 0 1 1.4 1.4v4.93h2.79M6.88 8.56a1.68 1.68 0 0 0 1.68-1.68c0-.93-.75-1.69-1.68-1.69a1.69 1.69 0 0 0-1.69 1.69c0 .93.76 1.68 1.69 1.68m1.39 9.94v-8.37H5.5v8.37h2.77z" },
                  { href: "https://github.com/codecraftedca", label: "GitHub", icon: "M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22" },
                  { href: "mailto:juanpablo@riano.ca", label: "Email", icon: "M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z M22 6l-10 7L2 6" },
                ].map(({ href, label, icon }) => (
                  <a
                    key={label}
                    href={href}
                    aria-label={label}
                    target={href.startsWith("http") ? "_blank" : undefined}
                    rel={href.startsWith("http") ? "noreferrer" : undefined}
                    className="w-9 h-9 flex items-center justify-center border border-[var(--border-1)] rounded-[var(--radius-sm)] text-[var(--text-3)] hover:text-[var(--text-1)] hover:border-[var(--border-2)] hover:bg-[var(--blue-dim)] transition-all duration-150"
                  >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                      <path d={icon} />
                    </svg>
                  </a>
                ))}
              </div>
            </div>

            {/* Services */}
            <div>
              <h5 className="font-mono text-[11px] tracking-[0.12em] text-[var(--text-3)] uppercase font-medium mb-4">
                {t("footer.services.title")}
              </h5>
              <ul className="flex flex-col gap-3">
                {(["scheduling","portals","automation","operations","platforms"] as const).map((k) => (
                  <li key={k}>
                    <Link to="/services/" className="font-body text-[13px] text-[var(--text-2)] hover:text-[var(--text-1)] transition-colors">
                      {t(`footer.services.${k}`)}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>

            {/* Industries */}
            <div>
              <h5 className="font-mono text-[11px] tracking-[0.12em] text-[var(--text-3)] uppercase font-medium mb-4">
                {t("footer.industries.title")}
              </h5>
              <ul className="flex flex-col gap-3">
                {[
                  { k: "trades",      to: "/industries/trades/" },
                  { k: "healthcare",  to: "/industries/healthcare/" },
                  { k: "professional",to: "/industries/professional/" },
                  { k: "realEstate",  to: "/industries/" },
                  { k: "education",   to: "/industries/" },
                ].map(({ k, to }) => (
                  <li key={k}>
                    <Link to={to} className="font-body text-[13px] text-[var(--text-2)] hover:text-[var(--text-1)] transition-colors">
                      {t(`footer.industries.${k}`)}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>

            {/* Company */}
            <div>
              <h5 className="font-mono text-[11px] tracking-[0.12em] text-[var(--text-3)] uppercase font-medium mb-4">
                {t("footer.company.title")}
              </h5>
              <ul className="flex flex-col gap-3">
                {[
                  { k: "process",     to: "/process/" },
                  { k: "caseStudies", to: "/case-studies/" },
                  { k: "about",       to: "/about/" },
                  { k: "contact",     to: "/contact/" },
                ].map(({ k, to }) => (
                  <li key={k}>
                    <Link to={to} className="font-body text-[13px] text-[var(--text-2)] hover:text-[var(--text-1)] transition-colors">
                      {t(`footer.company.${k}`)}
                    </Link>
                  </li>
                ))}
                <li>
                  <a href="mailto:hello@codecrafted.ca" className="font-body text-[13px] text-[var(--text-2)] hover:text-[var(--text-1)] transition-colors">
                    {t("footer.email")}
                  </a>
                </li>
              </ul>
            </div>
          </div>

          {/* Bottom bar */}
          <div className="mt-12 pt-5 border-t border-[var(--border-1)] flex flex-wrap items-center justify-center gap-3 font-mono text-[11px] text-[var(--text-3)] tracking-[0.06em]">
            <span>© {currentYear} {t("footer.copyright")}</span>
            <span className="opacity-50">·</span>
            <span>{t("footer.location")}</span>
            <span className="opacity-50">·</span>
            <span>EN · FR · ES</span>
            <span className="opacity-50">·</span>
            <button
              onClick={() => (window as any).__ccsOpenCookieManager?.()}
              className="hover:text-[var(--text-1)] transition-colors underline underline-offset-2"
            >
              {t("footer.manageCookies")}
            </button>
          </div>
        </div>
      </footer>

      <CookieBanner />
    </>
  );
};

export default Layout;
